<template><el-drawer :model-value="modelValue" :title="`任务详情 #${detail.task?.id??''}`" size="min(760px,92vw)" @update:model-value="$emit('update:modelValue',$event)"><div v-loading="loading"><el-descriptions v-if="detail.task" :column="2" border><el-descriptions-item label="类型">{{typeText(detail.task.task_type)}}</el-descriptions-item><el-descriptions-item label="状态"><StatusTag group="detection" :status="detail.task.status"/></el-descriptions-item><el-descriptions-item v-if="detail.task.username" label="用户">{{detail.task.username}} (#{{detail.task.user_id}})</el-descriptions-item><el-descriptions-item label="场景">{{detail.task.scene_name||'-'}}</el-descriptions-item><el-descriptions-item label="图片数">{{detail.task.total_images||0}}</el-descriptions-item><el-descriptions-item label="目标数">{{detail.task.total_objects||0}}</el-descriptions-item><el-descriptions-item label="推理耗时">{{detail.task.total_inference_time?`${detail.task.total_inference_time}ms`:'-'}}</el-descriptions-item><el-descriptions-item label="完成时间">{{formatDate(detail.task.completed_at)}}</el-descriptions-item><el-descriptions-item v-if="detail.task.error_message" label="失败原因" :span="2"><span class="error">{{detail.task.error_message}}</span></el-descriptions-item></el-descriptions><el-descriptions v-if="detail.report" :column="1" border class="report"><el-descriptions-item label="质检结论">{{detail.report.quality_conclusion||'-'}}</el-descriptions-item><el-descriptions-item label="风险等级"><StatusTag group="risk" :status="detail.report.risk_level||'none'"/></el-descriptions-item><el-descriptions-item label="风险原因">{{detail.report.risk_reason||'-'}}</el-descriptions-item><el-descriptions-item label="处理建议">{{detail.report.suggestion||'-'}}</el-descriptions-item></el-descriptions><EvidenceGallery :items="detail.items||[]" :task="detail.task"/><section v-if="Object.keys(detail.class_counts||{}).length" class="classes"><h3>类别分布</h3><el-tag v-for="(count,name) in detail.class_counts" :key="name">{{name}} × {{count}}</el-tag></section><section class="results"><h3>检测结果</h3><el-table :data="detail.results||[]" size="small" max-height="360"><el-table-column label="类别"><template #default="{row}">{{row.class_name_cn||row.class_name}}</template></el-table-column><el-table-column prop="confidence" label="置信度" width="90"/><el-table-column label="边界框" min-width="170"><template #default="{row}">{{Array.isArray(row.bbox)?row.bbox.map(n=>Math.round(n)).join(', '):'-'}}</template></el-table-column><template #empty><el-empty description="暂无检测结果" :image-size="60"/></template></el-table></section></div></el-drawer></template>
<script setup>import StatusTag from '@/components/common/StatusTag.vue';import EvidenceGallery from './EvidenceGallery.vue';defineProps({modelValue:Boolean,detail:{type:Object,default:()=>({task:null,class_counts:{},results:[]})},loading:Boolean,typeText:{type:Function,required:true}});defineEmits(['update:modelValue']);const formatDate=v=>v?new Date(v).toLocaleString('zh-CN'):'-'</script>
<style lang="scss" scoped>.report{margin-top:14px}.classes,.results{margin-top:18px}.classes h3,.results h3{color:$text-primary;font-size:15px}.classes .el-tag{margin:0 6px 6px 0}.error{color:$danger-color}</style>
